        holidays=['Independence Day (June 12)', 'Rizal Day (December 30)', 'Bonifacio Day (November 30)', 'People Power Revolution Day (February 25)', 'Maundy Thursday and Good Friday', 'All Saints\' Day (November 1)', 'Christmas Day', 'New Year\'s Day'],
