        unescoIntangible=['Alardah Alnajdiyah, dance, drumming and poetry in Saudi Arabia', 'Al-Qatt Al-Asiri, female traditional interior wall decoration in Asir', 'Traditional weaving of Al Sadu', 'Arabic coffee, a symbol of generosity', 'Date palm, knowledge, skills, traditions and practices', 'Arabic calligraphy: knowledge, skills and practices', 'Al-Mansaf / Culinary traditions'],
