        imports=['Crude petroleum and refined fuel products (via Iranian oil credit lines)', 'Wheat and grain commodities (primarily from Russia)', 'Industrial machinery, vehicles, and spare parts', 'Raw chemicals and plastics', 'Basic consumer goods and electronics'],
